change.old_schema:
syntax = "proto3";
package demo.inventory;
enum StockState { STOCK_UNKNOWN = 0; STOCK_AVAILABLE = 1; }
message StockItem {
  string sku = 1;
  int32 quantity = 2;
  repeated string labels = 3;
  StockState state = 4;
}

change.new_schema:
syntax = "proto3";
package demo.inventory;
enum StockState { STOCK_UNKNOWN = 0; STOCK_AVAILABLE = 1; STOCK_BACKORDERED = 2; }
message StockItem {
  string sku = 1;
  int32 quantity = 2;
  repeated string labels = 3;
  StockState state = 4;
}
